// 1. Parse the agent's JSON defensively - it may arrive fenced or with prose.
const raw = String($json.response ?? '').trim();

function extractJson(text) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = fenced ? fenced[1].trim() : text;
  try {
    return JSON.parse(candidate);
  } catch {}
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try {
      return JSON.parse(candidate.slice(start, end + 1));
    } catch {}
  }
  return null;
}

const stats = extractJson(raw);
const values = ($('Set Channel Config').item.json.values || []).map(Number).filter((n) => Number.isFinite(n));

if (!stats || values.length === 0) {
  return [{
    json: {
      ok: false,
      verified: false,
      reason: !stats
        ? 'Could not parse a JSON object from the agent response.'
        : 'No numeric values were supplied in the webhook body.',
      rawResponse: raw.slice(0, 600),
    },
  }];
}

// 2. Recompute every figure the workflow reports, and compare. The code
//    interpreter is exact, but any prose the model writes around the tool output
//    is not, so nothing is labelled verified unless it was checked here.
const sorted = [...values].sort((a, b) => a - b);
const mid = Math.floor(sorted.length / 2);

const local = {
  count: values.length,
  mean: values.reduce((a, b) => a + b, 0) / values.length,
  median: sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2,
  min: sorted[0],
  max: sorted[sorted.length - 1],
};
// Population standard deviation, matching statistics.pstdev in the prompt.
local.stdev = Math.sqrt(
  values.reduce((acc, v) => acc + (v - local.mean) ** 2, 0) / values.length,
);

function matches(reported, computed) {
  const r = Number(reported);
  if (!Number.isFinite(r)) return false;
  const tolerance = Math.max(1e-6, Math.abs(computed) * 1e-6);
  return Math.abs(r - computed) <= tolerance;
}

const fields = ['count', 'mean', 'median', 'stdev', 'min', 'max'];
const fieldChecks = {};
const mismatched = [];
for (const f of fields) {
  const ok = matches(stats[f], local[f]);
  fieldChecks[f] = ok;
  if (!ok) mismatched.push(f);
}

// The code interpreter must have run. A figure produced without it was predicted
// by the model, not computed, so it does not qualify as verified.
const codeInterpreterUsed = Array.isArray($json.toolUses)
  && $json.toolUses.some((t) => String(t?.name ?? '').includes('code_interpreter'));

const verified = mismatched.length === 0 && codeInterpreterUsed;

let note;
if (verified) {
  note = 'Every reported figure matches an independent recomputation in n8n.';
} else if (!codeInterpreterUsed) {
  note = 'The code interpreter did not run, so these figures came from the model rather than from executed code. Check that Add Tools is enabled.';
} else {
  note = `Mismatch against the local recomputation for: ${mismatched.join(', ')}. Do not trust these figures.`;
}

return [{
  json: {
    ok: true,
    verified,
    codeInterpreterUsed,
    label: stats.label ?? $('Set Channel Config').item.json.label,
    count: stats.count ?? local.count,
    mean: Number(stats.mean),
    median: stats.median ?? null,
    stdev: stats.stdev ?? null,
    min: stats.min ?? null,
    max: stats.max ?? null,
    check: {
      fields: fieldChecks,
      mismatched,
      recomputed: local,
      note,
    },
    latencyMs: $json.latencyMs ?? null,
  },
}];

